{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C64"],
      "claim": "Bumetanide, a highly ionized acidic sulfonamide/carboxylic acid, had 95% oral bioavailability in patients with cirrhosis, directly supporting high F for the query under the same condition despite unfavorable ionization/polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Tolfenamic acid, an acidic fenamate with a diarylamine core, showed about 100% oral bioavailability in alcoholic cirrhosis, supporting high F for the query's acidic sulfonylurea/diarylamine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Isradipine, with low healthy-subject bioavailability, increased to 37% in patients with biopsy-proven cirrhosis, demonstrating that cirrhosis can raise F above the 20% threshold and supporting a high prediction for the query under cirrhosis.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Safinamide had an absolute oral bioavailability of 95% in healthy subjects, a high-transfer analogue showing that polar/ionizable drugs can be nearly completely absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Imatinib, a large heteroaromatic drug with multiple ionizable centers, had 98% absolute oral bioavailability, supporting high F for the query's heteroaromatic/ionizable structure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer analogues with direct absolute oral bioavailability measurements, including in cirrhosis, show F ≥ 20% (bumetanide 95%, tolfenamic acid ~100%, isradipine 37% in cirrhosis, safinamide 95%, imatinib 98%). The query's acidic sulfonylurea/ionized character is consistent with the high F seen for bumetanide and tolfenamic acid; the physicochemical prior is overridden by stronger experimental evidence.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule itself.",
    "No query-specific metabolism or transporter-mediated absorption data.",
    "Cirrhosis effects are inferred from structurally related analogues rather than measured for the query.",
    "No experimental solubility or permeability data for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

